llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "The closest structural analogue, rilzabrutinib, which shares the same pyrazolopyrimidine-phenoxyphenyl-piperidine amide scaffold, had an estimated absolute oral bioavailability of only 4.7% (90% CI 3.2–7.1%) after a 400 mg oral tablet in humans, strongly indicating that this chemotype is prone to very low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Acalabrutinib, a more distant BTK inhibitor analogue, achieved an absolute oral bioavailability of 25% in healthy subjects, showing that some related inhibitors can exceed the 20% threshold, but its structural transferability to the query is limited.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest high-transfer analogue (rilzabrutinib) has an absolute oral bioavailability of only ~4.7%, and the query shares the same BTK-inhibitor core and acrylamide/piperidine/phenoxyphenyl features. Although a more distant BTK inhibitor reaches 25%, the strong transferable low-F evidence and the known first-pass liability of this scaffold support a low prediction under fed conditions.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself.",
    "No intravenous reference data for the query to calculate F directly.",
    "Fed-state effect on absolute bioavailability is not directly measured for the closest analogue.",
    "Structural differences between the query and rilzabrutinib (acrylamide vs cyanoacrylamide, absence of fluorine and piperazine-oxetane substituent) introduce uncertainty in transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

